import json,re
from html import unescape
s=json.load(open('source.json'));a=json.load(open('answer.json'))
for i in [9,10,13,14,17,18,20,21,22]:
 print('\\n###',a[i]['number'])
 p=re.findall(r'<p>(.*?)</p>',a[i]['proposed_xml'],re.S)
 if i==10: print(unescape(p[0]))
 elif i in [14]:print(unescape(p[0]));print(a[i]['review_notes'])
 else:print('\\n'.join(unescape(z) for z in p))
 if i==22:print(a[i]['review_notes'])
print('\\n### Renvois distincts')
pat=re.compile(r'\\b(?:L|R|D)\\.?\\s*\\d+[A-Za-z]*[-.]\\d+(?:[-.]\\d+)*')
norm=lambda x:re.sub(r'[.\\s]','',x)
for x,y in zip(s,a):
 old={norm(z) for z in pat.findall(unescape(x['source_xml']))}
 new={norm(z) for z in pat.findall(unescape(y['proposed_xml']))}
 if old-new or new-old:print(x['number'],'supprimés',old-new,'ajoutés',new-old)
PY"

